import json,glob,re
prot=json.load(open('fpbase.json'))
def seqs(f):
    txt=open(f).read().split('\n')
    s='';out=[]
    header=None
    for line in txt:
        if line.startswith('>'):
            if s:out.append(s)
            s=''
        else:s+=line.strip()
    if s:out.append(s)
    return out
# build fpbase seq map
def clean(s):return re.sub('[^A-Z]','',s.upper())
fp=[(p['name'],clean(p.get('seq') or ''),p.get('states')) for p in prot]
for f in sorted(glob.glob('pdb_*.fasta')):
    id=f.split('_')[1].split('.')[0]
    ss=seqs(f)
    chain=clean(ss[0])
    best=None;bestn=0
    for name,fseq,states in fp:
        if not fseq:continue
        # exact substring match
        if fseq in chain or chain in fseq:
            score=min(len(fseq),len(chain))
            if score>bestn:bestn=score;best=(name,states)
    if best:
        st=best[1][0] if best[1] else {}
        print(id, "->", best[0], "ex",st.get('ex_max'),"em",st.get('em_max'))
    else:
        print(id,"-> NO EXACT MATCH len",len(chain))
EOF

