cd /app; python3 - <<'EOF'
import json,glob,re,difflib
prot=json.load(open('fpbase.json'))
def clean(s):return re.sub('[^A-Z]','',s.upper())
def seqs(f):
    s='';out=[]
    for line in open(f):
        if line.startswith('>'):
            if s:out.append(s);s=''
        else:s+=line.strip()
    if s:out.append(s)
    return out
fp=[(p['name'],clean(p.get('seq') or ''),p.get('states')) for p in prot if p.get('seq')]
for f in sorted(glob.glob('pdb_*.fasta')):
    id=f.split('_')[1].split('.')[0]
    chain=clean(seqs(f)[0])
    scored=[]
    for name,fseq,states in fp:
        r=difflib.SequenceMatcher(None,chain,fseq).ratio()
        scored.append((r,name,states))
    scored.sort(reverse=True)
    r,name,states=scored[0]
    st=states[0] if states else {}
    print(f"{id} -> {name} ratio={r:.3f} ex={st.get('ex_max')} em={st.get('em_max')}")
EOF

