url="https://search.rcsb.org/rcsbsearch/v2/query?json="+urllib.parse.quote(json.dumps(q))
try:
    r=json.load(urllib.request.urlopen(url,timeout=40))
    for h in r['result_set'][:25]:
        print(h['identifier'],round(h['score'],3))
except Exception as e:
    print("ERR",e)
